#include "public_price_detail_page.hpp"
#include <QtWidgets>
using publicPriceDetail::need;
namespace {
class Plot final:public QWidget {
 QJsonArray rows;int interval=0;
public:
 explicit Plot(QWidget*parent):QWidget(parent){setObjectName("priceDetailPlot");setMinimumHeight(190);}
 void setRows(QJsonArray value,int seconds){rows=std::move(value);interval=seconds;update();}
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.setRenderHint(QPainter::Antialiasing);p.fillRect(rect(),palette().base());QRectF area=rect().adjusted(75,20,-20,-35);p.setPen(palette().mid().color());p.drawRect(area);if(rows.isEmpty()){p.setPen(palette().text().color());p.drawText(area,Qt::AlignCenter,"请明确选择证券与旧日期，再读取公开价格详情");return;}double low=1e100,high=-1e100;int first=86400,last=0;for(auto v:rows){auto r=v.toObject();double price=r["price"].toDouble();low=std::min(low,price);high=std::max(high,price);int t=publicPriceDetail::seconds(r["time"].toString().mid(11));first=std::min(first,t);last=std::max(last,t);}double span=std::max(high-low,0.01);p.setPen(palette().text().color());p.drawText(QRectF(0,area.top()-8,70,20),Qt::AlignRight,QString::number(high,'g',12));p.drawText(QRectF(0,area.bottom()-12,70,20),Qt::AlignRight,QString::number(low,'g',12));p.drawText(QRectF(area.left(),area.bottom()+8,120,20),QTime(first/3600,(first%3600)/60,first%60).toString("HH:mm:ss"));p.drawText(QRectF(area.right()-120,area.bottom()+8,120,20),Qt::AlignRight,QTime(last/3600,(last%3600)/60,last%60).toString("HH:mm:ss"));p.setPen(QPen(QColor("#409eff"),1.1));QPointF previous;int previousTime=-1;QString previousPhase;for(auto v:rows){auto r=v.toObject();int t=publicPriceDetail::seconds(r["time"].toString().mid(11));QPointF point(area.left()+double(t-first)/std::max(1,last-first)*area.width(),area.bottom()-(r["price"].toDouble()-low)/span*area.height());if(interval>0&&previousTime>=0&&t-previousTime<=interval&&r["phase"].toString()==previousPhase)p.drawLine(previous,point);else p.drawPoint(point);previous=point;previousTime=t;previousPhase=r["phase"].toString();}}
};
QString value(QJsonValue v){return v.isNull()||v.isUndefined()?"缺数":v.isString()?v.toString():QString::fromUtf8(QJsonDocument(QJsonArray{v}).toJson(QJsonDocument::Compact)).sliced(1).chopped(1);}
}
PublicPriceDetailPage::PublicPriceDetailPage(QString file,QWidget*parent):QWidget(parent),store(std::move(file)){
 setObjectName("publicPriceDetailPage");auto layout=new QVBoxLayout(this);auto boundary=new QLabel("历史公开价格详情 · 腾讯公开观测，不是逐笔、L2或交易所真值。原记录保留盘前/盘后状态；派生视图不补缺口、不代替五档盘口或虚拟竞价。");boundary->setTextFormat(Qt::PlainText);boundary->setWordWrap(true);layout->addWidget(boundary);auto tools=new QHBoxLayout;layout->addLayout(tools);instrument=new QComboBox;instrument->setObjectName("priceDetailInstrument");instrument->setMinimumContentsLength(22);day=new QComboBox;day->setObjectName("priceDetailDate");view=new QComboBox;view->setObjectName("priceDetailView");view->addItem("原公开报价记录",0);view->addItem("旧算法5秒派生",5);view->addItem("旧算法30秒派生",30);tools->addWidget(instrument,2);tools->addWidget(day,1);tools->addWidget(view,1);
 auto button=[&](QString text,QString name,std::function<void()>fn){auto b=new QPushButton(text);b->setObjectName(name);tools->addWidget(b);connect(b,&QPushButton::clicked,this,[this,b,fn]{if(isVisible()&&b->isVisible())guard(fn);});return b;};button("重读目录","priceDetailReload",[this]{reload(instrument->currentData().toString());});button("读取所选日期","priceDetailRead",[this]{readSelected();});button("清除 / 取消","priceDetailClear",[this]{cancel();});status=new QLabel;status->setObjectName("priceDetailStatus");status->setWordWrap(true);status->setTextFormat(Qt::PlainText);layout->addWidget(status);auto tabs=new QTabWidget;tabs->setObjectName("priceDetailTabs");layout->addWidget(tabs,1);auto data=new QWidget;auto dataLayout=new QVBoxLayout(data);plot=new Plot(this);dataLayout->addWidget(plot,2);table=new QTableWidget;table->setObjectName("priceDetailTable");table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setSelectionMode(QAbstractItemView::SingleSelection);table->setSortingEnabled(false);dataLayout->addWidget(table,3);auto pages=new QHBoxLayout;dataLayout->addLayout(pages);previous=new QPushButton("上一页");previous->setObjectName("priceDetailPrevious");next=new QPushButton("下一页");next->setObjectName("priceDetailNext");pageState=new QLabel;pageState->setObjectName("priceDetailPageState");pages->addWidget(previous);pages->addWidget(pageState,1);pages->addWidget(next);tabs->addTab(data,"历史价格与明细");auto raw=new QWidget;auto rawLayout=new QVBoxLayout(raw);auto readFull=new QPushButton("阅读完整原文件（保留全部原页与记录）");readFull->setObjectName("priceDetailReadSource");rawLayout->addWidget(readFull);reader=new QPlainTextEdit;reader->setObjectName("priceDetailRawReader");reader->setReadOnly(true);rawLayout->addWidget(reader,1);auto reading=new QHBoxLayout;rawLayout->addLayout(reading);readerPrevious=new QPushButton("上一段");readerPrevious->setObjectName("priceDetailRawPrevious");readerNext=new QPushButton("下一段");readerNext->setObjectName("priceDetailRawNext");readerState=new QLabel;readerState->setObjectName("priceDetailRawPosition");reading->addWidget(readerPrevious);reading->addWidget(readerState,1);reading->addWidget(readerNext);tabs->addTab(raw,"原记录 / 公开响应");
 connect(instrument,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{guard([this]{dates();});});connect(day,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{clear();status->setText("请核对旧日期后读取；不会替换为其它日期或最新报价。");});connect(view,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{guard([this]{render();});});connect(previous,&QPushButton::clicked,this,[this]{--tablePage;renderTable();});connect(next,&QPushButton::clicked,this,[this]{++tablePage;renderTable();});connect(table,&QTableWidget::cellClicked,this,[this](int row,int){guard([this,row]{showRow(tablePage*200+row);});});connect(readFull,&QPushButton::clicked,this,[this]{if(loaded.isEmpty())return;readerText=loaded["rawText"].toString();readerPage=0;renderReader();});connect(readerPrevious,&QPushButton::clicked,this,[this]{--readerPage;renderReader();});connect(readerNext,&QPushButton::clicked,this,[this]{++readerPage;renderReader();});guard([this]{reload();});
}
void PublicPriceDetailPage::guard(const std::function<void()>&work){try{work();}catch(const std::exception&e){clear();status->setText(QString::fromUtf8(e.what()));}}
void PublicPriceDetailPage::clear(){loaded={};rows={};readerText.clear();readerPage=0;tablePage=0;static_cast<Plot*>(plot)->setRows({},0);table->setRowCount(0);renderReader();pageState->setText("未读取");previous->setEnabled(false);next->setEnabled(false);}
void PublicPriceDetailPage::cancel(){clear();status->setText("读取已清除；没有采样、请求、任务、交易或文件写入。");}
void PublicPriceDetailPage::reload(QString preferred){clear();frames=store.catalogue();QSignalBlocker block(instrument);instrument->clear();instrument->addItem("请明确选择证券",QString());QSet<QString>seen;for(auto v:frames){auto m=v.toObject();auto id=m["nativeId"].toString();if(seen.contains(id))continue;seen.insert(id);instrument->addItem(id+" · "+m["name"].toString(),id);}int index=instrument->findData(preferred);if(index<0&&!preferred.isEmpty()){instrument->setItemText(0,"当前证券（无已存旧详情）："+preferred);instrument->setItemData(0,preferred);index=0;}instrument->setCurrentIndex(std::max(0,index));dates();}
void PublicPriceDetailPage::setInstrument(QString id){guard([this,id]{reload(id);});}
void PublicPriceDetailPage::dates(){clear();QSignalBlocker block(day);day->clear();day->addItem("请选择已保存的旧日期",QString());auto id=instrument->currentData().toString();for(auto v:frames){auto m=v.toObject();if(m["nativeId"]==id)day->addItem(m["tradingDate"].toString()+(m["available"].toBool()?"":"（原件缺失）"),m["tradingDate"].toString());}status->setText(day->count()>1?QString("此证券保存%1个旧日期，请明确选择；latest仅保留为来源指针。").arg(day->count()-1):"此完整证券身份没有已保存的旧公开价格详情；未按裸代码替换或创建数据。");}
void PublicPriceDetailPage::readSelected(){guard([this]{clear();loaded=store.read(instrument->currentData().toString(),day->currentData().toString());render();});}
void PublicPriceDetailPage::render(){if(loaded.isEmpty())return;auto s=loaded["snapshot"].toObject(),meta=loaded["metadata"].toObject();int interval=view->currentData().toInt();rows=interval?publicPriceDetail::aggregate(s["records"].toArray(),interval):s["records"].toArray();tablePage=0;readerText.clear();readerPage=0;renderReader();renderTable();static_cast<Plot*>(plot)->setRows(rows,interval);status->setText(meta["nativeId"].toString()+" · 原日期 "+s["tradingDate"].toString()+QString(" · 原记录%1条 / 本视图%2行 · 常见原间隔%3秒（不是逐笔精度）\n采集：%4 · 最后来源观测：%5 · paginationComplete=%6（只描述当时分页，不证明全天完整） · 盘后缺号%7\n%8\n原件：%9 · SHA256：%10 · 来源引用：%11").arg(s["records"].toArray().size()).arg(rows.size()).arg(value(s["modalIntervalSeconds"])).arg(s["fetchedAt"].toString(),s["providerObservedAt"].toString(),s["paginationComplete"].toBool()?"true":"false").arg(value(s["outsideSessionMissingRecords"])).arg(interval?"旧算法派生：桶尾时间；数量按原规则100股/手换算，金额沿用原值，未独立核实原字段单位。空值保留，不补桶、不计算均价。":"原数量/金额/方向均为公开原字段，未独立核实单位；价格及变动保留原字符写法。时刻字符串不补写时区。").arg(meta["sourceFile"].toString(),loaded["rawSha256"].toString(),QString::fromUtf8(QJsonDocument(meta["sourceRefs"].toArray()).toJson(QJsonDocument::Compact))));}
void PublicPriceDetailPage::renderTable(){const bool raw=view->currentData().toInt()==0;QStringList columns=raw?QStringList{"原记录ID","来源时间","原价格","变动原值","数量原值","金额原值","方向原值","原阶段"}:QStringList{"桶尾时间","开","高","低","末价","派生量（股）","金额原值","观测记录数","最后来源时刻","阶段"};table->clear();table->setColumnCount(columns.size());table->setHorizontalHeaderLabels(columns);int pages=std::max(1,int((rows.size()+199)/200));tablePage=std::max(0,std::min(tablePage,pages-1));int start=tablePage*200,end=std::min(start+200,int(rows.size()));table->setRowCount(end-start);for(int index=start;index<end;++index){auto r=rows[index].toObject();QStringList cells;if(raw){auto fields=r["raw"].toString().split('/');cells={fields.value(0),r["time"].toString(),fields.value(2),fields.value(3),r["quantityRaw"].toString(),r["amountRaw"].toString(),r["sideRaw"].toString(),r["phase"].toString()};}else for(auto key:{"time","open","high","low","price","volume","amount","observedCount","providerLastAt","phase"})cells.append(value(r[key]));for(int c=0;c<cells.size();++c)table->setItem(index-start,c,new QTableWidgetItem(cells[c]));}table->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);table->horizontalHeader()->setStretchLastSection(true);previous->setEnabled(tablePage>0);next->setEnabled(tablePage+1<pages);pageState->setText(QString("第%1/%2页 · 本视图完整%3行 · 每页200行，未截断").arg(tablePage+1).arg(pages).arg(rows.size()));}
void PublicPriceDetailPage::showRow(int index){need(index>=0&&index<rows.size(),"请明确选择当前页的一条记录");auto r=rows[index].toObject();readerText=(view->currentData().toInt()?"所选旧算法派生桶（不是逐笔）\n":"所选公开原记录\n")+QString::fromUtf8(QJsonDocument(r).toJson())+"\n原件来源\n"+QString::fromUtf8(QJsonDocument(loaded["metadata"].toObject()).toJson());if(view->currentData().toInt()==0)for(auto v:loaded["snapshot"].toObject()["rawPages"].toArray()){auto page=v.toObject();auto payload=publicPriceDetail::assignment(page["text"].toString(),"v_detail_data_"+loaded["snapshot"].toObject()["symbol"].toString());if(payload[1].toString().split('|').contains(r["raw"].toString())){readerText+="\n实际原公开响应页\n"+QString::fromUtf8(QJsonDocument(page).toJson());break;}}readerPage=0;renderReader();}
void PublicPriceDetailPage::renderReader(){const int size=48000;int pages=std::max(1,int((readerText.size()+size-1)/size));readerPage=std::max(0,std::min(readerPage,pages-1));int start=readerPage*size,end=std::min(start+size,int(readerText.size()));if(start>0&&start<readerText.size()&&readerText[start].isLowSurrogate())--start;if(end>0&&end<readerText.size()&&readerText[end].isLowSurrogate())--end;reader->setPlainText(readerText.mid(start,end-start));readerState->setText(QString("第%1/%2段 · 完整%3字，原文件和原页未裁剪").arg(readerPage+1).arg(pages).arg(readerText.size()));readerPrevious->setEnabled(readerPage>0);readerNext->setEnabled(readerPage+1<pages);}
